from lib import *
S = SS('f76')
R = J('f76'); cu = R['cost_us']; wk = R['workers']; wm, wr = list(wk.values())
steps = [
    step("固定窗口 5 per minute:7 次请求的状态码是 200 ×5 然后 429 ×2。响应头里有 X-RateLimit-Limit(5)、X-RateLimit-Remaining(第 1 次是 4,429 时是 0)、X-RateLimit-Reset(窗口结束的时间戳)和 Retry-After(60 秒);自定义 429 的 errorhandler 返回 JSON,detail 是「5 per 1 minute」。换一个客户端(X-Client: c2)不受影响。", t=tl(S(1)), done=lidx(S(1), '7 次请求', '第 1 次响应', '别的客户端'), mark=lidx(S(1), '429 的正文', '第 7 次'), kv=KV([['限制', '5 per minute'], ['超限', '429 + Retry-After'], ['按客户端', '各算各的']], ['超限'])),
    step("同一个路由可以有多个限制(\"3 per 10 seconds; 100 per hour\" 连发 5 次:200 ×3 再 429 ×2);shared_limit 让多个路由共用一个桶(4 per minute,交替请求 /s1 与 /s2 共 6 次:前 4 次 200,后 2 次 429);cost=5 的 \"10 per minute\" 只能连发 2 次;@limiter.exempt 的路由连发 30 次全是 200;只有默认限制的路由头里也有 X-RateLimit-*(1000,剩余 998)。", t=tl(S(2)), done=lidx(S(2), '共享桶', 'exempt'), mark=lidx(S(2), '3 per 10 seconds', 'cost=5'), kv=KV([['多个限制', '任一超限就 429'], ['shared_limit', '多个路由共用桶'], ['cost', '一次请求扣多个额度']], ['shared_limit'])),
    step("策略对比(限制 3 per 2 seconds):t=0 发 1 次,t=1.5 s 连发 3 次,t=2.2 s 再连发 3 次。fixed-window 的结果 [200, 200, 200, 429, 200, 200, 200]——窗口在 2 秒时整体重置,1.5 s 到 2.2 s 这 0.7 秒里放行了 5 次;moving-window 的结果 [200, 200, 200, 429, 200, 429, 429]——t=0 那一次滑出窗口后只多放行 1 次。", t=tl(S(3)), mark=lidx(S(3), 'fixed-window'), done=lidx(S(3), 'moving-window'), kv=KV([['fixed-window', '窗口边界可以突发约 2 倍'], ['moving-window', '更平滑,记录每次请求时间']], ['fixed-window'])),
    step(f"存储:memory:// 是每个进程自己的计数器。3 个 gunicorn worker、同一个客户端连发 30 次、限制 5 per minute:memory 放行 {wm} 次(约等于 5 × worker 数),自己起的 redis 存储放行 {wr} 次。redis 里的限流键是 LIMITS:LIMITER/<客户端>/<端点>/5/1/minute,值是计数,TTL 60 秒。", b=bars([['memory://', wm, f'{wm} 次'], ['redis', wr, f'{wr} 次']], 30, mark=[0], done=[1]), t=tl(S(4)), done=lidx(S(4), 'redis'), mark=lidx(S(4), 'memory'), kv=KV([['memory://', '每个 worker 各一份,实际限额 × worker 数'], ['redis', '所有 worker 共享']], ['memory://'])),
    step("key_func 决定按谁限流。这里的 key_func 在没有 X-Client 头时回退到 get_remote_address;7 个带不同 X-Forwarded-For 的请求被当成同一个客户端(5 次 200、2 次 429)——因为没配置代理头的信任,remote_addr 是直连方的地址。在反向代理后面部署必须处理这个(见第 135 篇)。", t=tl(S(5)), mark=lidx(S(5), '不同 X-Forwarded-For'), kv=KV([['get_remote_address', '用 remote_addr'], ['代理后面', '所有人同一个 IP']], ['代理后面'])),
    step(f"开销:test client 3000 次一组取最小,无限流 {cu[0]:.0f} µs/请求,memory 存储的限流 {cu[1]:.0f} µs/请求,多出约 {cu[1] - cu[0]:.0f} µs。redis 存储每个请求多一次网络往返,这个数字没有量。", b=bars([['无限流', cu[0], f'{cu[0]:.0f} µs'], ['memory 限流', cu[1], f'{cu[1]:.0f} µs']], cu[1], done=[0, 1]), t=tl(S(6)), done=lidx(S(6), '多出'), kv=KV([['memory 限流', f'约 +{cu[1] - cu[0]:.0f} µs/请求']], ['memory 限流'])),
]
A = mkartf('f76', 76, 'Flask,Flask-Limiter,限流,429,Redis,真实验证,动画演示',
    f'实测 Flask-Limiter:固定窗口 5 per minute 的 200/429 与 X-RateLimit、Retry-After 头;多个限制、共享限制、cost、exempt;fixed-window 与 moving-window 在窗口边界的差别;memory 存储下 3 个 worker 放行 {wm} 次而 redis 只放行 {wr} 次;代理后面按 IP 限流的陷阱;memory 限流每请求多约 {cu[1] - cu[0]:.0f} µs。',
    '给接口加限流,响应头里有什么?固定窗口和滑动窗口有什么区别?多 worker 部署时 memory 存储还有效吗?在代理后面按 IP 限流为什么会误伤?这篇用真实的 gunicorn 与自己起的 redis 逐项验证。',
    [(f'{wm} 次 vs {wr} 次', '3 个 worker、限制 5 per minute 时 memory 与 redis 存储的实际放行数'), ('5 次', 'fixed-window 在 0.7 秒的窗口边界放行的次数(限制 3 per 2 seconds)'), (f'{cu[1] - cu[0]:.0f} µs', 'memory 存储下限流每个请求多出的耗时(test client)')],
    [('固定窗口与响应头', '<p>上一篇:<a href="flask-flask-caching.html">Flask-Caching</a>;下一篇:<a href="flask-flask-mail.html">Flask-Mail</a>。</p>'), ('多限制、共享、cost、exempt', None), ('fixed-window 与 moving-window', None), ('存储与多 worker', '<p>redis 是自己在非默认端口起的临时实例,验证完就关闭了。</p>'), ('key_func 与代理', None), ('限流的开销', None)],
    steps, [ENV_F + '。Flask-Limiter 4.1.1、limits 5.8.0、自己起的 redis', '没有验证:sliding-window-counter 策略、redis 存储每请求多出的网络往返耗时、redis 不可用时 in_memory_fallback 的行为、真实反向代理下配合 ProxyFix 的取值、分布式部署下时钟偏差的影响'], 'Flask-Limiter', panels=[('t', 'term', '实验输出'), ('b', 'bars', '数量 / 耗时'), ('kv', 'kv', '要点')])
